"""Discard Hold'em primitives (numpy only): cards, evaluator, discard heuristic, 3-card preflop
table, and Monte-Carlo equity that understands the discard stage.

Cards are ints 0..51: rank = c >> 2 (0='2' ... 12='A'), suit = c & 3 with suit order s,h,d,c
(the order the rulebook uses for discard tie-breaks).
"""
import itertools
import numpy as np

RANKS = "23456789TJQKA"
SUITS = "shdc"
_R = np.arange(13)
_B = 14


def parse_card(s):
    return RANKS.index(s[0]) * 4 + SUITS.index(s[1])


def card_str(c):
    return RANKS[c >> 2] + SUITS[c & 3]


# ----------------------------------------------------------------------------- evaluator
COMBOS = {k: np.array(list(itertools.combinations(range(k), 5)), dtype=np.int64) for k in (5, 6, 7)}


def eval5(cards):
    """cards (M,5) -> (M,) int64 score, higher is better."""
    r = cards >> 2
    s = cards & 3
    cnt = (r[:, :, None] == _R).sum(axis=1)
    key = np.where(cnt > 0, cnt * 16 + _R, 0)
    sk = -np.sort(-key, axis=1)[:, :5]
    c = sk >> 4
    rk = np.where(sk > 0, (sk & 15) + 1, 0)
    enc = (((rk[:, 0] * _B + rk[:, 1]) * _B + rk[:, 2]) * _B + rk[:, 3]) * _B + rk[:, 4]
    c1, c2 = c[:, 0], c[:, 1]
    flush = (s == s[:, :1]).all(axis=1)
    distinct = c1 == 1
    straight = distinct & (rk[:, 0] - rk[:, 4] == 4)
    wheel = distinct & (rk[:, 0] == 13) & (rk[:, 1] == 4)
    enc = np.where(wheel, 4 * _B ** 4, enc)
    st = straight | wheel
    cat = np.select([st & flush, c1 == 4, (c1 == 3) & (c2 == 2), flush, st, c1 == 3, (c1 == 2) & (c2 == 2), c1 == 2],
                    [8, 7, 6, 5, 4, 3, 2, 1], default=0)
    return cat * _B ** 5 + enc


def eval_best(cards):
    n, k = cards.shape
    if k == 5:
        return eval5(cards)
    idx = COMBOS[k]
    return eval5(cards[:, idx].reshape(n * len(idx), 5)).reshape(n, len(idx)).max(axis=1)


# ----------------------------------------------------------------------------- discard heuristic
_WIN = np.zeros((10, 13), dtype=bool)
for _w in range(9):
    _WIN[_w, _w:_w + 5] = True
_WIN[9, [12, 0, 1, 2, 3]] = True          # A-2-3-4-5


def keep_score(keep, flop):
    """Heuristic value of keeping `keep` (M,2) given `flop` (M,3): made-hand strength plus draw bonus."""
    five = np.concatenate([keep, flop], axis=1)
    base = eval5(five) / float(_B ** 5)
    suits = five & 3
    fd = ((suits[:, :, None] == np.arange(4)).sum(axis=1).max(axis=1) == 4)
    present = (five >> 2)[:, :, None] == _R
    present = present.any(axis=1)                                       # (M,13)
    cnt = present.astype(np.int8) @ _WIN.T.astype(np.int8)              # (M,10)
    miss = _WIN[None, :, :] & ~present[:, None, :]
    outs = ((cnt == 4)[:, :, None] & miss).any(axis=1).sum(axis=1)
    made = (cnt == 5).any(axis=1)
    sd = np.where(made, 0.0, np.where(outs >= 2, 0.6, np.where(outs == 1, 0.25, 0.0)))
    return base + 0.8 * fd + sd


def keep_best(cards3, flop):
    """Heuristic discard. cards3 (M,3), flop (M,3) -> (disc_idx (M,), kept (M,2))."""
    K = np.stack([cards3[:, [1, 2]], cards3[:, [0, 2]], cards3[:, [0, 1]]], axis=1)    # (M,3,2): keep when discarding i
    sc = np.stack([keep_score(K[:, i], flop) for i in range(3)], axis=1)
    disc = sc.argmax(axis=1)
    return disc, K[np.arange(len(cards3)), disc]


def lowest_discard(cards3):
    """Index the rulebook default (and the starter bot) would discard: lowest rank, ties by suit order s,h,d,c."""
    return int(min(range(3), key=lambda i: ((cards3[i] >> 2), cards3[i] & 3)))


# ----------------------------------------------------------------------------- 3-card preflop table
def triple_key(a, b, c):
    cs = sorted([(a >> 2, a & 3), (b >> 2, b & 3), (c >> 2, c & 3)], key=lambda x: (-x[0], x[1]))
    r0, r1, r2 = cs[0][0], cs[1][0], cs[2][0]
    s0, s1, s2 = cs[0][1], cs[1][1], cs[2][1]
    if s0 == s1 == s2:
        pat = 'm'
    elif s0 == s1:
        pat = 'ab'
    elif s0 == s2:
        pat = 'ac'
    elif s1 == s2:
        pat = 'bc'
    else:
        pat = 'r'
    if r0 == r1 == r2:
        pat = 'r'
    elif r0 == r1 and pat == 'bc':
        pat = 'ac'
    elif r1 == r2 and pat == 'ab':
        pat = 'ac'
    return (r0, r1, r2, pat)


_T = None
_T_SORTED = None


def preflop_array():
    """(52,52,52) float32 equity-vs-random lookup, and the sorted distribution for percentiles."""
    global _T, _T_SORTED
    if _T is None:
        TABLE = _TABLE
        _T = np.zeros((52, 52, 52), dtype=np.float32)
        vals = []
        for a, b, c in itertools.combinations(range(52), 3):
            v = TABLE[triple_key(a, b, c)]
            vals.append(v)
            for p in itertools.permutations((a, b, c)):
                _T[p] = v
        _T_SORTED = np.sort(np.array(vals, dtype=np.float32))
    return _T


def preflop_value(hole3):
    T = preflop_array()
    return float(T[hole3[0], hole3[1], hole3[2]])


def preflop_pct(hole3):
    preflop_array()
    return float(np.searchsorted(_T_SORTED, preflop_value(hole3)) / len(_T_SORTED))


# ----------------------------------------------------------------------------- simulation
def _deck(used):
    m = np.ones(52, dtype=bool)
    m[list(used)] = False
    return np.nonzero(m)[0]


def _draw(deck, N, need, rng):
    perm = np.argsort(rng.random((N, len(deck))), axis=1)[:, :need]
    return deck[perm]


def _stack_board(board, N):
    return np.broadcast_to(np.asarray(board, dtype=np.int64), (N, len(board)))


def _narrow(mask, st, q):
    if q >= 0.999 or mask.sum() < 20:
        return mask
    thr = np.quantile(st[mask], 1 - q)
    m2 = mask & (st >= thr)
    return m2 if m2.sum() >= 20 else mask


def sim_flop3(hole3, flop, q=1.0, n=300, rng=None):
    """Flop, before the discard: equity of each of the 3 possible keeps vs a random opponent 3-card hand
    (who also discards by heuristic), optionally narrowed to the top-q by the opponent's best keep."""
    rng = rng or np.random.default_rng()
    hole3 = np.asarray(hole3, dtype=np.int64)
    flop = np.asarray(flop, dtype=np.int64)
    deck = _deck(set(hole3.tolist()) | set(flop.tolist()))
    N = int(min(n / max(q, 0.1), 6 * n)) if q < 0.999 else n
    d = _draw(deck, N, 5, rng)
    opp3, run = d[:, :3], d[:, 3:]
    fl = _stack_board(flop, N)
    _, okeep = keep_best(opp3, fl)
    full = np.concatenate([fl, run], axis=1)
    mask = np.ones(N, dtype=bool)
    if q < 0.999:
        mask = _narrow(mask, keep_score(okeep, fl), q)
    theirs = eval_best(np.concatenate([okeep, full], axis=1))
    eqs = []
    for i in range(3):
        keep = np.delete(hole3, i)
        mine = eval_best(np.concatenate([np.broadcast_to(keep, (N, 2)), full], axis=1))
        o = (mine > theirs) + 0.5 * (mine == theirs)
        eqs.append(float(o[mask].mean()))
    return eqs


def sim_post(keep2, board, opp_disc, q=1.0, n=300, rng=None, eps=0.15):
    """After the discard: my 2 cards vs the opponent's 2 unknown cards, conditioned on their public discard."""
    rng = rng or np.random.default_rng()
    keep2 = np.asarray(keep2, dtype=np.int64)
    board = np.asarray(board, dtype=np.int64)
    nb = len(board)
    deck = _deck(set(keep2.tolist()) | set(board.tolist()) | {int(opp_disc)})
    N = int(min(n * 3 / max(q, 0.15), 8 * n))
    d = _draw(deck, N, 2 + 5 - nb, rng)
    opp, run = d[:, :2], d[:, 2:]
    trip = np.concatenate([opp, np.full((N, 1), opp_disc, dtype=np.int64)], axis=1)
    dd, _ = keep_best(trip, _stack_board(board[:3], N))
    consistent = (dd == 2) | ((opp_disc >> 2) <= (opp >> 2).min(axis=1))      # heuristic keep OR lowest-card discard
    mask = consistent | (rng.random(N) < eps)
    bd = _stack_board(board, N)
    if q < 0.999:
        mask = _narrow(mask, eval_best(np.concatenate([opp, bd], axis=1)), q)
    full = np.concatenate([bd, run], axis=1)
    mine = eval_best(np.concatenate([np.broadcast_to(keep2, (N, 2)), full], axis=1))
    theirs = eval_best(np.concatenate([opp, full], axis=1))
    o = (mine > theirs) + 0.5 * (mine == theirs)
    return float(o[mask].mean())


def sim_pre(hole3, q=1.0, n=300, rng=None):
    """Preflop equity vs the top-q (by preflop table) of 3-card hands, both sides discarding by heuristic."""
    rng = rng or np.random.default_rng()
    hole3 = np.asarray(hole3, dtype=np.int64)
    deck = _deck(set(hole3.tolist()))
    N = int(min(n / max(q, 0.1), 6 * n)) if q < 0.999 else n
    d = _draw(deck, N, 8, rng)
    opp3, board = d[:, :3], d[:, 3:]
    mask = np.ones(N, dtype=bool)
    if q < 0.999:
        T = preflop_array()
        mask = _narrow(mask, T[opp3[:, 0], opp3[:, 1], opp3[:, 2]], q)
    flop = board[:, :3]
    _, okeep = keep_best(opp3, flop)
    _, hkeep = keep_best(np.broadcast_to(hole3, (N, 3)), flop)
    mine = eval_best(np.concatenate([hkeep, board], axis=1))
    theirs = eval_best(np.concatenate([okeep, board], axis=1))
    o = (mine > theirs) + 0.5 * (mine == theirs)
    return float(o[mask].mean())

"""Discard Hold'em bot (protocol 1.0). Equity-driven, range-aware, time-governed.

- No cross-hand card memory (replay inference is deliberately NOT implemented; see DH_SPEC_DIGEST.md).
- Opponent model = aggregate action frequencies by spot (spotq), which is ordinary opponent modelling.
- Any exception falls back to: check if legal else fold (discard: lowest rank), exactly the engine's own default.
"""
import json, sys, time, os
import numpy as np

PRIORS = {'lead': 0.40, 'vs_bet': 0.20, 'pre_open': 0.50, 'pre_3bet': 0.15}
N0 = 8


class Bot:
    def __init__(self, seed=None, fixed_n=None, clock=time.perf_counter, **kw):
        self.rng = np.random.default_rng(seed)
        self.fixed_n = fixed_n                       # None = time governor; int = deterministic sims (experiments)
        self.clock = clock
        self.total_hands = 400
        self.hand_id = 0
        self.hole, self.opp_disc = [], None
        self.flop_q = 1.0
        self.spot = {k: [p * N0, N0] for k, p in PRIORS.items()}     # [aggressive actions, opportunities]
        self.faced, self.folded = 3.0, 1.0                           # opponent facing OUR bets / folding to them
        self.ms_per_sim = 0.25
        self.errors = 0
        self.done = False
        self.pre_faced, self.pre_folded = 4.0, 1.0                    # opponent facing OUR preflop raise / folding
        self.cons = [0.85 * 8.0, 8.0]                                # opp discards consistent with a sensible policy
        self.p = dict(open_btn=0.40, defend_btn=0.10, iso_bb=0.55, ex=1.0, eps=1.0, tie=1.0)
        self.p.update(kw.get('params', {}) or {})

    # ------------------------------------------------------------------ protocol
    def handle(self, m):
        t = m.get('type')
        try:
            if t == 'init':
                self.total_hands = int(m.get('total_hands', 400))
            elif t == 'new_hand':
                self.hand_id = int(m['hand_id'])
                self.hole = [parse_card(c) for c in m['hole_cards']]
                self.opp_disc = None
                self.flop_q = 1.0
            elif t == 'discard_result':
                self.hole = [parse_card(c) for c in m['hole_cards']]
                self.opp_disc = parse_card(m['opp_discard'])
            elif t == 'hand_result':
                self._learn(m.get('history', []))
                self._learn_discard(m)
            elif t == 'match_end':
                self.done = True
            elif t == 'action_request':
                try:
                    return self._act(m)
                except Exception:
                    self.errors += 1
                    return self._fallback_action(m)
            elif t == 'discard_request':
                try:
                    return self._discard(m)
                except Exception:
                    self.errors += 1
                    hc = [parse_card(c) for c in m['hole_cards']]
                    return {'type': 'discard', 'card': card_str(hc[lowest_discard(hc)])}
        except Exception:
            self.errors += 1
        return None

    @staticmethod
    def _fallback_action(m):
        legal = m.get('legal_actions', [])
        return {'type': 'action', 'action': 'check' if 'check' in legal else ('fold' if 'fold' in legal else 'call')}

    # ------------------------------------------------------------------ opponent model
    def _learn(self, history):
        """Rebuild the hand from the complete history and update spot frequencies (no cards are stored)."""
        bets = {'me': 0, 'opp': 0}
        street = None
        for h in history:
            a, who = h['action'], h['actor']
            if h['street'] != street:
                street = h['street']
                if street == 'preflop':      # blinds are not listed; the button (1) acts first preflop
                    bets = {'opp': 1, 'me': 2} if who == 'opp' else {'me': 1, 'opp': 2}
                else:
                    bets = {'me': 0, 'opp': 0}
            tc = bets['me' if who == 'opp' else 'opp'] - bets[who]
            if who == 'opp':
                if street == 'preflop':
                    spot = 'pre_open' if bets['me'] <= 2 else 'pre_3bet'
                else:
                    spot = 'lead' if tc == 0 else 'vs_bet'
                c = self.spot[spot]
                c[1] += 1
                c[0] += a == 'raise'
                if street != 'preflop' and tc > 0:         # postflop response to our bet (preflop folds excluded)
                    self.faced += 1
                    self.folded += a == 'fold'
                elif street == 'preflop' and tc > 0 and bets['me'] > 2:   # response to our preflop raise (not to the blind)
                    self.pre_faced += 1
                    self.pre_folded += a == 'fold'
            if a in ('call', 'raise'):
                bets[who] = h.get('amount', bets[who])

    def _learn_discard(self, m):
        """At showdown the opponent's full 3-card hand is public: was their discard what a sensible policy does?
        Only a counter is kept (no cards)."""
        try:
            if m.get('result') != 'showdown' or not m.get('opp_discard') or not m.get('opp_hole_cards'):
                return
            trip = np.array([[parse_card(c) for c in m['opp_hole_cards']] + [parse_card(m['opp_discard'])]])
            flop = np.array([[parse_card(c) for c in m['board'][:3]]])
            d, _ = keep_best(trip, flop)
            ok = int(d[0]) == 2 or (trip[0, 2] >> 2) <= (trip[0, :2] >> 2).min()
            self.cons[1] += 1
            self.cons[0] += bool(ok)
        except Exception:
            self.errors += 1

    @property
    def disc_eps(self):
        """Weight given to opponent hands whose discard looks inconsistent with a sensible policy."""
        if not self.p['eps']:
            return 0.15
        return float(min(0.9, max(0.05, 1.0 - self.cons[0] / self.cons[1])))

    @property
    def fold_rate(self):
        return self.folded / self.faced

    @property
    def obs_conf(self):
        """Evidence gate: 0 until we have seen a few opponent responses, 1 after ~12 (priors count as 4)."""
        return float(min(1.0, max(0.0, (self.faced - 4.0) / 12.0)))

    def _range_q(self, req):
        if req['street'] == 'preflop':
            spot = 'pre_open' if req['my_bet'] <= 2 else 'pre_3bet'
        else:
            spot = 'lead' if req['my_bet'] == 0 else 'vs_bet'
        k, n = self.spot[spot]
        frac = req['to_call'] / max(req['pot'] - req['to_call'], 1)
        size_adj = min(1.2, max(0.6, (0.6 / max(frac, 0.05)) ** 0.3))
        return min(1.0, max(0.08, (k / n) * size_adj))

    # ------------------------------------------------------------------ time governor
    def _n(self, base, req):
        if self.fixed_n:
            return self.fixed_n
        tl = req.get('time_left_ms', 60000)
        hands_left = max(1, self.total_hands - self.hand_id + 1)
        spendable = max(tl - 4000.0, 0.0) * 0.40                    # keep a reserve and only plan to use ~40% of the rest
        per_req = spendable / hands_left / 4.0                      # up to ~4 sim-requests per hand
        n = int(per_req / self.ms_per_sim)
        return 0 if tl < 2500 else int(min(max(n, 30), 2 * base))

    def _timed(self, fn, n, *a, **k):
        t0 = self.clock()
        out = fn(*a, n=n, rng=self.rng, **k)
        self.ms_per_sim = 0.8 * self.ms_per_sim + 0.2 * ((self.clock() - t0) * 1000 / max(n, 1))
        return out

    # ------------------------------------------------------------------ decisions
    def _raise_to(self, req, frac):
        tc, pot, ob = req['to_call'], req['pot'], req['opp_bet']
        t = int(round(ob + frac * (pot + tc)))
        t = max(req['min_raise'], min(t, req['max_raise']))
        if t >= 0.6 * req['max_raise']:
            t = req['max_raise']
        return {'type': 'action', 'action': 'raise', 'amount': int(t)}

    @staticmethod
    def _act_simple(kind):
        return {'type': 'action', 'action': kind}

    def _equity(self, req):
        board = [parse_card(c) for c in req['board']]
        tc = req['to_call']
        facing = req['opp_bet'] > 2 if req['street'] == 'preflop' else tc > 0
        q = self._range_q(req) if facing else 1.0
        if req['street'] == 'preflop':
            if not facing:
                return preflop_value(self.hole), False
            n = self._n(250, req)
            if n == 0:
                return preflop_value(self.hole), True
            return self._timed(sim_pre, n, self.hole, q=q), True
        n = self._n(300, req)
        if len(self.hole) == 3:                                     # flop betting, before the discard
            self.flop_q = q if facing else self.flop_q
            if n == 0:
                return 0.5, facing
            return max(self._timed(sim_flop3, n, self.hole, board, q=q)), facing
        if n == 0:
            return 0.5, facing
        return self._timed(sim_post, n, self.hole, board, self.opp_disc, q=q, eps=self.disc_eps), facing

    def _act(self, req):
        legal = req['legal_actions']
        can_raise = 'raise' in legal
        tc = req['to_call']
        e, facing = self._equity(req)
        r = self.rng.random()
        if req['street'] == 'preflop' and not facing:
            p = preflop_pct(self.hole)
            if tc > 0:                                                 # button, first to act
                open_thr = self.p['open_btn']
                if self.p['ex']:                                        # steal wider against opponents that fold to raises
                    pf = self.pre_folded / self.pre_faced
                    pc = min(1.0, max(0.0, (self.pre_faced - 4.0) / 10.0))
                    open_thr *= 1.0 - pc * min(1.0, max(0.0, (pf - 0.3) / 0.3))
                if can_raise and p >= open_thr:
                    return self._raise_to(req, 1.0)
                return self._act_simple('call' if p >= self.p['defend_btn'] else 'fold')
            if can_raise and p >= self.p['iso_bb']:                     # big blind facing a limp
                return self._raise_to(req, 0.9)
            return self._act_simple('check')

        pot = req['pot']
        need = tc / (pot + tc) if tc else 0.0
        if tc > 0:
            if can_raise and (e > 0.80 or (e > 0.68 and r < 0.4)):
                return self._raise_to(req, 0.8)
            if e >= need + 0.04:
                return self._act_simple('call')
            if can_raise and e > 0.25 and r < 0.06 + 0.15 * max(0.0, self.fold_rate - 0.4):
                return self._raise_to(req, 0.8)
            return self._act_simple('fold')
        fr, conf = self.fold_rate, self.obs_conf
        station = bool(self.p['ex']) and fr < 0.25 and conf > 0                # calls too much: value-bet thinner, never bluff
        if can_raise and e > (0.55 if station else 0.62):
            return self._raise_to(req, 0.75 if station else 0.65) if r < 0.9 else self._act_simple('check')
        if can_raise and e > 0.45:
            return self._raise_to(req, 0.33) if r < 0.2 else self._act_simple('check')
        bluff = min(0.5, max(0.05, 0.12 + 0.9 * (fr - 0.35)))
        if self.p['ex']:
            bluff = 0.0 if station else min(0.65, max(0.05, 0.12 + 0.9 * (fr - 0.35)) * (0.5 + 0.5 * conf) + (0.1 * conf if fr > 0.6 else 0.0))
        if can_raise and r < bluff:
            return self._raise_to(req, 0.6)
        return self._act_simple('check')

    def _discard(self, req):
        hole = [parse_card(c) for c in req['hole_cards']]
        flop = [parse_card(c) for c in req['board']]
        n = self._n(300, req)
        if n == 0:
            d, _ = keep_best(np.array([hole]), np.array([flop]))
            i = int(d[0])
        else:
            eqs = self._timed(sim_flop3, n, hole, flop, q=self.flop_q)
            i = int(np.argmax(eqs))
            if self.p['tie']:        # near-equal: discard the lowest card (simulation noise should not pick randomly)
                near = [j for j in range(3) if eqs[j] >= max(eqs) - 0.01]
                i = min(near, key=lambda j: (hole[j] >> 2, hole[j] & 3))
        return {'type': 'discard', 'card': card_str(hole[i])}


def main():
    seed = os.environ.get('BOT_SEED')
    bot = Bot(seed=int(seed) if seed else None)
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            msg = json.loads(line)
        except ValueError:
            continue
        if not isinstance(msg, dict):
            continue
        reply = bot.handle(msg)
        if reply is not None:
            out.write(json.dumps(reply) + '\n')
            out.flush()
        if bot.done:
            break


if __name__ == '__main__':
    main()
